window.docContents[166].resolve({"/2___-Basic-notions-of-representation-theory/2___3___-Representations/Introduction-to-Schur___s-lemma/#Chapter2___Discussion_Schur_intro":{"contents":"We will now prove our first result — Schur's lemma. Although it is very easy to prove, it is fundamental in the whole subject of representation theory.\n\n\n","context":"Introduction to Representation Theory\t2. Basic notions of representation theory\t2.3. Representations\tIntroduction to Schur's lemma","header":"Introduction to Schur's lemma","id":"/2___-Basic-notions-of-representation-theory/2___3___-Representations/Introduction-to-Schur___s-lemma/#Chapter2___Discussion_Schur_intro"},"/3___-General-results-of-representation-theory/3___8___-The-Krull-Schmidt-theorem/#chapter-03___section-3-8":{"contents":"\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Introduction to Representation Theory\t3. General results of representation theory","header":"3.8. The Krull-Schmidt theorem","id":"/3___-General-results-of-representation-theory/3___8___-The-Krull-Schmidt-theorem/#chapter-03___section-3-8"},"/5___-Representations-of-finite-groups___-Further-results/5___8___-Induced-representations/Section-5___8___-Induced-representations-___-restriction-and-induction/#Chapter5___Introduction_5___8___heading-1":{"contents":"Given a representation V of a group G and a subgroup H \\subset G, there is a natural way to construct a representation of H. The restriction of V to H, \\operatorname{Res}_H^G V is the representation given by the vector space V, and the action \\rho_{\\operatorname{Res}_H^G V} = \\rho_V|_H.\n\nThere is also a natural, but less trivial, way to construct a representation of a group G given a representation V of its subgroup H.\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.8. Induced representations\tSection 5.8: Induced representations — restriction and induction","header":"5.8. Induced representations","id":"/5___-Representations-of-finite-groups___-Further-results/5___8___-Induced-representations/Section-5___8___-Induced-representations-___-restriction-and-induction/#Chapter5___Introduction_5___8___heading-1"},"/8___-Homological-algebra/8___2___-Tor-and-Ext-functors/Tor-and-Ext-in-abelian-categories-with-enough-projectives/#Chapter8___Discussion_after_Problem8___2___8":{"contents":"In a similar way one can define Tor and Ext groups in any abelian category which has enough projectives; i.e., any object is a quotient of a projective object (this condition insures that every object has a projective resolution).\n\n\n\n","context":"Introduction to Representation Theory\t8. Homological algebra\t8.2. Tor and Ext functors\tTor and Ext in abelian categories with enough projectives","header":"Tor and Ext in abelian categories with enough projectives","id":"/8___-Homological-algebra/8___2___-Tor-and-Ext-functors/Tor-and-Ext-in-abelian-categories-with-enough-projectives/#Chapter8___Discussion_after_Problem8___2___8"}});
